Item.method_code:
const view = inDom.getAttribute('action') !== 'add' && aras.isAdminUser() ? 'DefaultItemWindowView' : 'MassPromoteWindowView';
return window.ModulesManager.using(
	[`aras.innovator.core.ItemWindow/${view}`,
	'aras.innovator.core.ItemWindow/DefaultItemWindowCreator'], function(View, Creator) {
		const view = new View(inDom, inArgs);
		const creator = new Creator(view);
		return creator.ShowView();
	});
